.cp-desk table{width:100%;min-width:760px;border-collapse:collapse;font-size:.84rem;text-align:left}
.cp-desk th,.cp-desk td{padding:.65rem .7rem;border-bottom:1px solid #d7dadc;vertical-align:top;overflow-wrap:anywhere;max-width:30rem}
.cp-desk th{background:#edf0f1;color:#202428;font-weight:650;white-space:nowrap}
.cp-desk td:nth-last-child(2){font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.8rem}
.cp-desk details>summary{cursor:pointer;overflow-wrap:anywhere}
.cp-desk .cp-file-list{display:flex;flex-direction:column;gap:.5rem;margin-top:.6rem}
.cp-desk .cp-file-list p{margin:0}
.cp-desk progress{width:100%;max-width:40rem;height:.65rem;accent-color:#343b40}
.cp-desk .status.error{color:#202428;border-left:3px solid #24292d;padding-left:.8rem;font-weight:600}
.cp-desk :focus-visible{outline:2px solid #222d36;outline-offset:3px}
.cp-desk .cp-guide{max-width:90ch}
@media(max-width:600px){
 .cp-desk .section-heading{display:block}
 .cp-desk .section-heading>button{margin-top:.5rem}
 .cp-desk .cp-box{padding:.8rem}
 .cp-desk .cp-tabs{gap:.3rem}
